<div class="highlight hl-python"><pre><span></span><span class="c1"># Заполняем пропущенные значения предыдущими покупками клиента</span>
<span class="n">df_repeat_customers</span><span class="p">[</span><span class="s1">'product_category_name'</span><span class="p">]</span> <span class="o">=</span> <span class="p">(</span>
    <span class="n">df_repeat_customers</span><span class="o">.</span><span class="n">groupby</span><span class="p">(</span><span class="s1">'customer_id'</span><span class="p">)[</span><span class="s1">'product_category_name'</span><span class="p">]</span>
    <span class="o">.</span><span class="n">transform</span><span class="p">(</span><span class="k">lambda</span> <span class="n">x</span><span class="p">:</span> <span class="n">x</span><span class="o">.</span><span class="n">ffill</span><span class="p">()</span><span class="o">.</span><span class="n">combine_first</span><span class="p">(</span><span class="n">x</span><span class="p">))</span>
<span class="p">)</span>

<span class="c1"># Если остались еще пропуски, заполняем их 'Unknown'</span>
<span class="n">df_repeat_customers</span><span class="p">[</span><span class="s1">'product_category_name'</span><span class="p">]</span><span class="o">.</span><span class="n">fillna</span><span class="p">(</span><span class="s1">'Unknown'</span><span class="p">,</span> <span class="n">inplace</span><span class="o">=</span><span class="kc">True</span><span class="p">)</span>

<span class="c1"># display(df_repeat_customers)</span>
<span class="c1">#df_repeat_customers.info()</span>
</pre></div>
