</div><div class="jp-Cell jp-CodeCell jp-Notebook-cell">
<div class="jp-Cell-inputWrapper" tabindex="0">
<div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser">
</div>
<div class="jp-InputArea jp-Cell-inputArea">

<div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
<div class="cm-editor cm-s-jupyter">
<div class="highlight hl-python"><pre><span></span><span class="k">def</span> <span class="nf">print_row_info</span><span class="p">(</span><span class="n">row_index</span><span class="p">):</span>
    <span class="c1"># Проверяем, существует ли строка с данным индексом</span>
    <span class="k">if</span> <span class="n">row_index</span> <span class="o">&lt;</span> <span class="mi">0</span> <span class="ow">or</span> <span class="n">row_index</span> <span class="o">&gt;=</span> <span class="nb">len</span><span class="p">(</span><span class="n">merged_df</span><span class="p">):</span>
        <span class="nb">print</span><span class="p">(</span><span class="s2">"Ошибка: Неверный номер строки."</span><span class="p">)</span>
        <span class="k">return</span>

    <span class="c1"># Получаем строку по индексу</span>
    <span class="n">row</span> <span class="o">=</span> <span class="n">merged_df</span><span class="o">.</span><span class="n">iloc</span><span class="p">[</span><span class="n">row_index</span><span class="p">]</span>

    <span class="c1"># Создаем HTML-вывод с большим шрифтом</span>
    <span class="n">output</span> <span class="o">=</span> <span class="sa">f</span><span class="s2">"&lt;h2&gt;Информация об абоненте:&lt;/h2&gt;"</span>
    <span class="k">for</span> <span class="n">column</span> <span class="ow">in</span> <span class="n">merged_df</span><span class="o">.</span><span class="n">columns</span><span class="p">:</span>
        <span class="n">output</span> <span class="o">+=</span> <span class="sa">f</span><span class="s2">"&lt;h3&gt;</span><span class="si">{</span><span class="n">column</span><span class="si">}</span><span class="s2">:&lt;/h3&gt;"</span>
        <span class="c1"># Проверяем тип данных перед заменой</span>
        <span class="k">if</span> <span class="nb">isinstance</span><span class="p">(</span><span class="n">row</span><span class="p">[</span><span class="n">column</span><span class="p">],</span> <span class="nb">str</span><span class="p">):</span>
            <span class="n">formatted_text</span> <span class="o">=</span> <span class="n">row</span><span class="p">[</span><span class="n">column</span><span class="p">]</span><span class="o">.</span><span class="n">replace</span><span class="p">(</span><span class="s1">'</span><span class="se">\n</span><span class="s1">'</span><span class="p">,</span> <span class="s1">'&lt;br&gt;'</span><span class="p">)</span>
        <span class="k">else</span><span class="p">:</span>
            <span class="n">formatted_text</span> <span class="o">=</span> <span class="nb">str</span><span class="p">(</span><span class="n">row</span><span class="p">[</span><span class="n">column</span><span class="p">])</span>  <span class="c1"># Преобразуем в строку, если это не строка</span>
        <span class="n">output</span> <span class="o">+=</span> <span class="sa">f</span><span class="s2">"&lt;p style='font-size: 15px;'&gt;</span><span class="si">{</span><span class="n">formatted_text</span><span class="si">}</span><span class="s2">&lt;/p&gt;"</span>  <span class="c1"># Изменяем размер шрифта</span>

    <span class="n">display</span><span class="p">(</span><span class="n">HTML</span><span class="p">(</span><span class="n">output</span><span class="p">))</span>

<span class="c1"># Пример использования функции</span>
<span class="n">row_number</span> <span class="o">=</span> <span class="nb">int</span><span class="p">(</span><span class="nb">input</span><span class="p">(</span><span class="s2">"Введите номер строки (с 1 по 3689): "</span><span class="p">))</span>
<span class="n">print_row_info</span><span class="p">(</span><span class="n">row_number</span><span class="p">)</span>
</pre></div>
